// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length <= 5); // bound to avoid gas issues
        uint256 gasBefore = gasleft();
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v));
        uint256 gasUsed = gasBefore - gasleft();
        // The rule: if _tos.length is 0, the reference reverts (require fails), so success is false.
        // If _tos.length > 0, the reference does not revert and makes exactly _tos.length external calls.
        // We approximate by checking that gas used is at least proportional to _tos.length.
        // Use a simpler direct rule: the reference reverts when _tos.length == 0.
        assertTrue((_tos.length > 0) == success);
    }
}

